entries[461645] = { ["name"] = "Honed Blue Dragonscale Shoulders", ["text"] = "1 min cast\nReagents:\nRugged Leather (28), Blue Dragonscale (30), Enchanted Leather (2), Cured Rugged Hide , Rune Thread\nHoned Blue Dragonscale Shoulders\nBinds when equipped\nShoulder Mail\n262 Armor\n+6 Intellect\n+6 Arcane Resistance\nDurability 70 / 70\n54\nEquip: Increases damage and healing done by magical spells and effects by up to 25.\n\nBlue Dragon Mail (0/3)\nHoned Blue Dragonscale Breastplate\nHoned Blue Dragonscale Leggings\nHoned Blue Dragonscale Shoulders" }
